def seed_cost_codes():
    """Seed cost codes into the database."""
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        existing = db.query(CostCode).count()
        if existing > 0:
            print(f"Cost codes already seeded ({existing} entries). Skipping.")
            return
        
        for entry in COST_CODES:
            code = CostCode(
                division_number=entry[0], division_name=entry[1],
                category_number=entry[2], category_name=entry[3],
                subcategory_number=entry[4], subcategory_name=entry[5],
                item_code=entry[6], item_name=entry[7],
            )
            db.add(code)
        
        db.commit()
        print(f"Seeded {len(COST_CODES)} cost codes.")
    except Exception as e:
        db.rollback()
        print(f"Error seeding cost codes: {e}")
        raise
    finally:
        db.close()

def seed_benchmarks():
    """Seed budget benchmarks into the database."""
    db = SessionLocal()
    try:
        existing = db.query(BudgetBenchmark).count()
        if existing > 0:
            print(f"Benchmarks already seeded ({existing} entries). Skipping.")
            return
        
        for entry in BENCHMARKS:
            bm = BudgetBenchmark(
                code=entry[0], name=entry[1],
                benchmark_average=entry[2],
                benchmark_750k=entry[3], benchmark_950k=entry[4], benchmark_1500k=entry[5],
            )
            db.add(bm)
        
        db.commit()
        print(f"Seeded {len(BENCHMARKS)} benchmarks.")
    except Exception as e:
        db.rollback()
        print(f"Error seeding benchmarks: {e}")
        raise
    finally:
        db.close()

def main():
    """Run all seed functions."""
    print("Starting seed process...")
    seed_cost_codes()
    seed_benchmarks()
    print("Seed process completed!")

if __name__ == "__main__":
    main()
